function validate(input) {
  const [array, spec] = input;
  if (!Array.isArray(array) || array.length > 100000) return 'array must be a JSON array of at most 10^5 elements.';
  let keyOf = null;
  if (spec === 'string') keyOf = (item) => String(item);
  else if (spec !== null && typeof spec === 'object' && !Array.isArray(spec) && Object.keys(spec).length === 1) {
    if (typeof spec.get === 'string' || Number.isInteger(spec.get)) {
      if (!array.every(item => item !== null && typeof item === 'object')) return 'With get, every element must be an object or an array.';
      keyOf = (item) => String(item[spec.get]);
    } else if (typeof spec.greaterThan === 'number' || Number.isInteger(spec.mod) && spec.mod !== 0) {
      if (!array.every(item => typeof item === 'number')) return 'With greaterThan or mod, every element must be a number.';
      keyOf = 'mod' in spec ? (item) => String(item % spec.mod) : (item) => String(item > spec.greaterThan);
    }
  }
  if (!keyOf) return 'fn must be "string", { "get": k }, { "greaterThan": v } or { "mod": m } with m not 0.';
  if (array.some(item => keyOf(item) === '__proto__')) return 'No key may be "__proto__".';
  return null;
}

