function adapt(input, solve, kit) {
  const [array, spec] = input;
  if (typeof array.groupBy !== 'function') throw new Error('Arrays have no groupBy method yet: assign a function to Array.prototype.groupBy.');
  const keyOf = spec === 'string' ? (item) => String(item)
    : 'get' in spec ? (item) => String(item[spec.get])
    : 'greaterThan' in spec ? (item) => String(item > spec.greaterThan)
    : (item) => String(item % spec.mod);
  const fn = (item) => {
    const key = keyOf(item);
    kit.trace(`fn(${JSON.stringify(item)}) returns "${key}"`);
    return key;
  };
  const before = JSON.stringify(array);
  const groups = array.groupBy(fn);
  if (groups === null || typeof groups !== 'object' || Array.isArray(groups)) throw new Error('groupBy must return a plain object of groups.');
  if (JSON.stringify(array) !== before) throw new Error('groupBy must not change the array.');
  // Any key order is accepted, so list the keys in one fixed order.
  const answer = Object.fromEntries(Object.keys(groups).sort().map(key => [key, groups[key]]));
  kit.trace(`array.groupBy(fn) returns ${Object.keys(answer).length} groups`);
  return answer;
}

