Array.prototype.groupBy = function (fn) {
  // Compute every key first, then gather each distinct key's elements with filter.
  const keys = this.map((item) => fn(item));
  const result = new Map();
  for (const key of new Set(keys)) {
    result.set(key, this.filter((item, i) => keys[i] === key));
  }
  return Object.fromEntries(result);
};

