function generate(rand, size) {
  const small = size === 'small';
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const length = small ? Math.floor(rand() * 7) : 2000;
  const kind = pick(['string', 'id', 'index', 'greaterThan', 'mod']);
  if (kind === 'string') {
    const values = [0, 1, 2, '1', 'a', '', 'toString', 'constructor', true, 'true', null, [1], [1, 2], '1,2'];
    return [Array.from({ length }, () => pick(values)), 'string'];
  }
  if (kind === 'id') {
    const ids = small ? ['1', '2', 'a', 'toString'] : Array.from({ length: 50 }, (_, i) => String(i));
    const array = Array.from({ length }, (_, i) => (rand() < 0.1 ? { n: i } : { id: pick(ids), n: i }));
    return [array, { get: 'id' }];
  }
  if (kind === 'index') {
    const array = Array.from({ length }, () => Array.from({ length: Math.floor(rand() * 4) }, () => Math.floor(rand() * 4)));
    return [array, { get: 0 }];
  }
  const top = small ? 10 : 100000;
  const array = Array.from({ length }, () => Math.floor(rand() * (2 * top + 1)) - top);
  if (kind === 'greaterThan') return [array, { greaterThan: Math.floor(rand() * (top + 1)) - Math.floor(top / 2) }];
  return [array, { mod: pick([1, 2, 3, 7, -4, small ? 5 : 97]) }];
}
